import numpy as np, math
from scipy.optimize import brentq
n=150000; m=7; lnn=math.log(n); Ht=lnn-10
def Hh(a): return -(a*math.log(a)+(1-a)*math.log((1-a)/(m-1)))
def F(a,t):
    # direct formula avoiding array
    qa=a; qb=(1-a)/(m-1)
    b=t/(n-m)
    return lnn + (m-1)*(1-t)*qb*math.log((1-t)*qb) + (1-t)*a*math.log((1-t)*a) + (n-m)*b*math.log(b)
def B(a,t):
    qa=a; qb=(1-a)/(m-1); b=t/(n-m)
    return -lnn - ((1-t)*math.log((1-t)*a)+(m-1)*(1-t)*math.log((1-t)*qb)+(n-m)*math.log(b))/n
def solve_t(a):
    def f(logt): return F(a,math.exp(logt))-10
    xs=np.linspace(math.log(1e-14), math.log(0.9), 2000)
    px=xs[0]; pv=f(px)
    for x in xs[1:]:
        cv=f(x)
        if pv*cv<=0:
            return math.exp(brentq(f,px,x))
        px=x; pv=cv
    return None
for a in np.linspace(0.2310,0.2350,41):
    if Hh(a)>=Ht:
        print('skip',a)
        continue
    t=solve_t(a)
    if t is None:
        print('no root',a,Hh(a))
    else:
        print(f"a={a:.9f} delta={Ht-Hh(a):.6e} t={t:.12e} b={t/(n-m):.6e} F={F(a,t):.9f} B={B(a,t):.9f} Bdiff={B(a,t)-10:+.6f}")
